const PROPS=new Set(['value','checked','disabled','hidden','selected','open']);
function h(tag,props,...kids){const n=document.createElement(tag);if(props)for(const k in props){const v=props[k];if(PROPS.has(k)){n[k]=v;continue;}if(v==null||v===false)continue;if(k==='class')n.className=v;else if(k==='text')n.textContent=v;else if(k==='style')n.style.cssText=v;else if(k.startsWith('on'))n.addEventListener(k.slice(2),v);else n.setAttribute(k,v===true?'':v);}kids.flat().forEach(c=>{if(c==null||c===false)return;n.append(c.nodeType?c:document.createTextNode(c));});return n;}
