function say(m,warn){statusEl.textContent=m;statusEl.classList.toggle('warn',!!warn);clearTimeout(statusT);statusT=setTimeout(()=>{statusEl.textContent='';},9000);}

// ====================================================================== color + noise
function hex2rgb(x){x=String(x||'#000').replace('#','');if(x.length===3)x=x.split('').map(c=>c+c).join('');const n=parseInt(x,16)||0;return[n>>16&255,n>>8&255,n&255];}
function mix(a,b,t){const A=hex2rgb(a),B=hex2rgb(b);return'#'+A.map((v,i)=>Math.round(v+(B[i]-v)*t).toString(16).padStart(2,'0')).join('');}
function rgba(x,a){const r=hex2rgb(x);return`rgba(${r[0]},${r[1]},${r[2]},${a})`;}
function rng(seed){let a=(seed|0)*2654435761+0x9e3779b9;return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function noise1(seed){const r=rng(seed),g=Array.from({length:256},r);return x=>{const i=Math.floor(x),f=x-i,u=f*f*(3-2*f);return g[i&255]+(g[(i+1)&255]-g[i&255])*u;};}

