let RD=null,VARS={},RB=0,RW=1100,RH=700,RK=1,EDIT=false;
const col=v=>{if(!v)return null;if(v[0]==='@')return(RD&&RD.pal[v.slice(1)])||'#000000';return v;};
const fam=v=>{if(!v)v='@body';if(v[0]==='@')v=(RD&&RD.fonts[v.slice(1)])||'Inter';return v;};
